#region Purpose
// Emits a module initializer that records this compilation's open-generic IPipelineBehavior definitions.
#endregion

#region Design
// The runtime log matches service descriptors against PipelineBehaviorRegistry instead of calling GetInterfaces.
// Only a class the generated file can name is recorded: public or internal, not private, protected, or file-local.
// Abstract classes are skipped. The service collection still supplies pipeline order. Nothing is emitted when
// this compilation declares no such behavior, or when IPipelineBehavior is not referenced.
#endregion

namespace TimeWarp.State.SourceGenerator;

[Generator]
public sealed class PipelineBehaviorRegistrySourceGenerator : IIncrementalGenerator
{
  private const string BehaviorMetadataName = "TimeWarp.Mediator.IPipelineBehavior`2";

  public void Initialize(IncrementalGeneratorInitializationContext context)
  {
    context.RegisterSourceOutput
    (
      context.CompilationProvider,
      static (sourceContext, compilation) => Execute(compilation, sourceContext)
    );
  }

  private static void Execute(Compilation compilation, SourceProductionContext sourceContext)
  {
    if (compilation.GetTypeByMetadataName(BehaviorMetadataName) is not INamedTypeSymbol behavior)
    {
      return;
    }

    List<INamedTypeSymbol> definitions = [];
    Collect(compilation.Assembly.GlobalNamespace, behavior, definitions);
    if (definitions.Count == 0)
    {
      return;
    }

    definitions.Sort(static (left, right) => string.CompareOrdinal(Display(left), Display(right)));
    StringBuilder builder = new();
    builder.AppendLine("// <auto-generated/>");
    builder.AppendLine("#nullable enable");
    builder.AppendLine();
    builder.AppendLine("namespace TimeWarp.State.Pipeline");
    builder.AppendLine("{");
    builder.AppendLine("  file static class PipelineBehaviorRegistrations");
    builder.AppendLine("  {");
    builder.AppendLine("    [global::System.Runtime.CompilerServices.ModuleInitializer]");
    builder.AppendLine("    internal static void Register()");
    builder.AppendLine("    {");
    foreach (INamedTypeSymbol definition in definitions)
    {
      builder.AppendLine($"      global::TimeWarp.State.PipelineBehaviorRegistry.Register(typeof({Display(definition)}), typeof(global::TimeWarp.Mediator.IPipelineBehavior<,>));");
    }

    builder.AppendLine("    }");
    builder.AppendLine("  }");
    builder.AppendLine("}");
    sourceContext.AddSource("TimeWarpPipelineBehaviors.g.cs", SourceText.From(builder.ToString(), Encoding.UTF8));
  }

  private static void Collect(INamespaceSymbol namespaceSymbol, INamedTypeSymbol behavior, List<INamedTypeSymbol> definitions)
  {
    foreach (INamespaceSymbol child in namespaceSymbol.GetNamespaceMembers())
    {
      Collect(child, behavior, definitions);
    }

    foreach (INamedTypeSymbol type in namespaceSymbol.GetTypeMembers())
    {
      CollectType(type, behavior, definitions);
    }
  }

  private static void CollectType(INamedTypeSymbol type, INamedTypeSymbol behavior, List<INamedTypeSymbol> definitions)
  {
    foreach (INamedTypeSymbol nested in type.GetTypeMembers())
    {
      CollectType(nested, behavior, definitions);
    }

    if (type.TypeKind != TypeKind.Class || type.IsAbstract)
    {
      return;
    }

    if (!type.IsGenericType || !type.IsDefinition || !CanName(type))
    {
      return;
    }

    foreach (INamedTypeSymbol implemented in type.AllInterfaces)
    {
      if (SymbolEqualityComparer.Default.Equals(implemented.OriginalDefinition, behavior))
      {
        definitions.Add(type);
        return;
      }
    }
  }

  private static string Display(INamedTypeSymbol type) =>
    type.ConstructUnboundGenericType().ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);

  private static bool CanName(INamedTypeSymbol type)
  {
    for (ISymbol? symbol = type; symbol is not null and not INamespaceSymbol; symbol = symbol.ContainingSymbol)
    {
      if (symbol is INamedTypeSymbol { IsFileLocal: true })
      {
        return false;
      }

      if (symbol.DeclaredAccessibility is Accessibility.Private or Accessibility.Protected or Accessibility.ProtectedAndInternal)
      {
        return false;
      }
    }

    return true;
  }
}
